            loc,
            messageId: "untagged",
            data: { corpus: CORPUS[kind], requirement: REQUIREMENT[kind] },
        };
    }
    return {
        loc,
        messageId: "statusMismatch",
        data: {
            corpus: CORPUS[kind],
            actual: mismatch.actual,
            expected: statusLabel(mismatch.expected, kind),
            linked: mismatch.linked,
            testable: mismatch.testable,
        },
    };
